return {["fb09_01"]={["dsc"]=[[这里是金陵的南门，高高的城墙上面插着几个旗帜，城门口站着几个值勤的官兵，你朝他们瞧了一眼，其中一个官兵冷冷地盯了你一眼，你不禁打了个哆嗦，还是快点走吧。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb09_01]],["name"]=[[南门]],["permission"]=2,["role1"]=[[fb09r01_1]],["role2"]=[[fb09r01_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb09_03]],["visible"]=1},["fb09_02"]={["BgmDown"]=1,["dsc"]=[[为孔庙俗称，又称文庙，是供奉和祭祀孔子的地方，以其“青砖小瓦马头墙、回廊挂落花格窗”的建筑风格称颂一时。游人学子络绎不绝。无不想瞻仰下孔子的风貌。]],["enterable"]=1,["id"]=[[fb09_02]],["item1"]=[[cgbftrigger04]],["name"]=[[夫子庙]],["permission"]=2,["right"]=[[fb09_03]],["role1"]=[[fb09r02_1]],["role2"]=[[21xiaohannpc01_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb09_03"]={["down"]=[[fb09_01]],["dsc"]=[[这里是金陵镇南边的主要街道，往北通往镇上最热闹的广场，往南则通往南门，你的左边是一座夫子庙，街道上人来人往，一派繁华的景象。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb09_03]],["item1"]=[[xcdfwp]],["item2"]=[[cgbftrigger03]],["item3"]=[[4qidraddqi1]],["item4"]=[[21masktrigger01]],["left"]=[[fb09_02]],["name"]=[[南街]],["permission"]=2,["right"]=[[fb09_33]],["role1"]=[[fb09r03_1]],["role2"]=[[fb09r03_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb09_06]],["visible"]=1},["fb09_04"]={["BgmDown"]=1,["dsc"]=[[这里是一间中药铺，进得店来，一股药香扑鼻而来，令你精神为之一震。这里的药品种类齐全，从珍贵的补药到平常的草药无一而不足。]],["enterable"]=1,["id"]=[[fb09_04]],["item1"]=[[lylitem1]],["name"]=[[中药铺]],["permission"]=2,["role1"]=[[fb09r04_1]],["role2"]=[[ever04_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb09_10]],["visible"]=1},["fb09_05"]={["BgmDown"]=1,["dsc"]=[[因这里服务一流加上各类鲜花都是上好的名品，所以一般价格较高，主要是作为传达情意的名贵礼品。]],["enterable"]=1,["id"]=[[fb09_05]],["item1"]=[[QXitem4]],["name"]=[[花店]],["permission"]=2,["right"]=[[fb09_06]],["role1"]=[[fb09r05_1]],["role2"]=[[QXr05_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb09_06"]={["down"]=[[fb09_03]],["dsc"]=[[这里是金陵镇南边的主要街道，往北通往镇上最热闹的广场，往南则通往南门，你的左边是一家花店，街道上人来人往，一派繁华的景象。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb09_06]],["item1"]=[[fb09item1]],["item2"]=[[QXitem3]],["left"]=[[fb09_05]],["name"]=[[南街]],["permission"]=2,["right"]=[[fb09_07]],["role1"]=[[fb09r06_1]],["role2"]=[[fb09r06_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb09_12]],["visible"]=1},["fb09_07"]={["BgmDown"]=1,["dsc"]=[[你走进一间堆满了布匹的店铺，原来是一家裁缝店。看这里一副生意兴隆的样子，往来者不乏高官显贵就可知道这里的手艺一定不凡，你要是有兴趣的话可以在这里定做衣裳。]],["enterable"]=1,["id"]=[[fb09_07]],["left"]=[[fb09_06]],["name"]=[[裁缝店]],["permission"]=2,["role1"]=[[fb09r07_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb09_08"]={["dsc"]=[[这里是金陵最大的一座酒楼了，酒楼坐落在秦淮河岸，两岸迤俪的风光尽收眼底。和友人傍窗而坐，要三两小菜，清酒一壶，评江湖韵事，论天下英雄，真是快意非凡。]],["enterable"]=1,["id"]=[[fb09_08]],["item1"]=[[QX7item5]],["name"]=[[酒楼]],["permission"]=2,["role1"]=[[fb09r08_1]],["role2"]=[[fb09r08_2]],["role3"]=[[fb09r08_3]],["role4"]=[[QXr08_1]],["roomBgm"]=[[chalou]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[jiaobu]],["up"]=[[fb09_13]],["visible"]=1},["fb09_09"]={["dsc"]=[[这里是金陵的西门，高高的城墙上面插着几个旗帜，城门口站着几个值勤的官兵，你朝他们瞧了一眼，其中一个官兵冷冷地盯了你一眼，你不禁打了个哆嗦，还是快点走吧。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb09_09]],["item1"]=[[fb09item2]],["name"]=[[西门]],["permission"]=2,["right"]=[[fb09_10]],["role1"]=[[fb09r09_1]],["role2"]=[[fb09r09_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb09_10"]={["down"]=[[fb09_04]],["dsc"]=[[这里是金陵镇西边的主要街道，往东通往镇上最热闹的广场，往西则通往西门，街道上人来人往，一派繁华的景象。北面好像有一家绸缎铺，南面是一家中药铺。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb09_10]],["item1"]=[[21drtrigger01]],["left"]=[[fb09_09]],["name"]=[[西街]],["permission"]=2,["right"]=[[fb09_11]],["role1"]=[[fb09r10_1]],["role2"]=[[fb09r10_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb09_15]],["visible"]=1},["fb09_11"]={["dsc"]=[[这里是金陵镇西边的主要街道，往东通往镇上最热闹的广场，往西则通往西门，街道上人来人往，一派繁华的景象。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb09_11]],["left"]=[[fb09_10]],["name"]=[[西街]],["permission"]=2,["right"]=[[fb09_12]],["role1"]=[[fb09r11_1]],["role2"]=[[fb09r11_4]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb09_12"]={["down"]=[[fb09_06]],["dsc"]=[[这里是金陵市的市中心，连接着金陵城的主要街道。古都金陵历来是历史名城。秦淮风光更是天下闻名。引得不少风流人士不远千里来此一游。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb09_12]],["item1"]=[[bfitem3]],["item2"]=[[cg2item6]],["item3"]=[[cgbftrigger02]],["left"]=[[fb09_11]],["name"]=[[中心广场]],["permission"]=1,["right"]=[[fb09_13]],["role1"]=[[fb09r12_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb09_17]],["visible"]=1},["fb09_13"]={["down"]=[[fb09_08]],["dsc"]=[[这里是金陵镇东边的主要街道，往西通往镇上最热闹的广场，往东则通往东门，街道上人来人往，一派繁华的景象。南面好像有一家酒楼。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb09_13]],["item1"]=[[QXitem1]],["item2"]=[[bfitem2]],["left"]=[[fb09_12]],["name"]=[[东街]],["permission"]=2,["right"]=[[fb09_14]],["role1"]=[[fb09r13_1]],["role2"]=[[fb09r20_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb09_23]],["visible"]=1},["fb09_14"]={["dsc"]=[[“锦绣十里春风来，千门万户临河开”，这里是金陵城的繁华地带，许多豪门世家、权贵差不多都聚居于淮水两岸，许多名胜古迹、历史掌故、风流韵事，都发生在它的身旁。]],["enterable"]=1,["id"]=[[fb09_14]],["item1"]=[[QX7item4]],["item2"]=[[21xiaohanquest2]],["item3"]=[[2021fhddd1]],["item4"]=[[4qiqinggong]],["left"]=[[fb09_13]],["name"]=[[秦淮河]],["permission"]=2,["right"]=[[fb09_36]],["role1"]=[[fb09r14_1]],["role2"]=[[fb09r14_2]],["role3"]=[[fb09r14_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb09_19]],["visible"]=1},["fb09_15"]={["BgmDown"]=1,["down"]=[[fb09_10]],["dsc"]=[[你走进一间堆满了布匹的店铺，原来是一家绸缎铺。从来来往往的人中，可以看出这里的生意不错。这里是专门卖布的地方，可是不管做衣服的。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb09_15]],["item1"]=[[QXitem2]],["item2"]=[[bf2088dj]],["name"]=[[绸缎铺]],["permission"]=2,["role1"]=[[fb09r15_1]],["role2"]=[[fb09r15_2]],["role3"]=[[QXr15_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb09_16"]={["BgmDown"]=1,["dsc"]=[[这里是金陵城的天马当铺，由于财资雄厚，你可以在这里典当任何物品。由于这里人来人往。因此不时这里也能有一些贵重的宝物出售。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb09_16]],["name"]=[[当铺]],["permission"]=2,["right"]=[[fb09_17]],["role1"]=[[fb09r16_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb09_17"]={["down"]=[[fb09_12]],["dsc"]=[[这里是金陵镇北边的主要街道，往南通往镇上最热闹的广场，往北则通往长江边，你的左边是当铺，右边是一家武器店，街道上人来人往，一派繁华的景象。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb09_17]],["left"]=[[fb09_16]],["name"]=[[北街]],["permission"]=1,["right"]=[[fb09_18]],["role1"]=[[fb09r17_1]],["role2"]=[[fb09r17_2]],["role3"]=[[fb09r17_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb09_21]],["visible"]=1},["fb09_18"]={["dsc"]=[[这里是金陵城的武器店。出售各种兵器，虽没有什么神兵利器，但所做的的兵器也都可以称的上是利器，而且种类齐全，价格适中，深受江湖人士的欢迎。]],["enterable"]=1,["id"]=[[fb09_18]],["left"]=[[fb09_17]],["name"]=[[武器店]],["permission"]=2,["role1"]=[[fb09r18_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb09_19"]={["down"]=[[fb09_14]],["dsc"]=[[这里是秦淮河上的一个画舫。整坐画舫华丽非凡，但最主要的是这里的姑娘们都可以说是色艺双绝，上至将相王侯，下至商贾文士无不闻名而来，欲一睹芳姿。]],["enterable"]=1,["id"]=[[fb09_19]],["item1"]=[[bfitem1]],["item2"]=[[yylbsdj2]],["item3"]=[[cgbftrigger01]],["name"]=[[画舫]],["permission"]=2,["role1"]=[[fb09r19_1]],["role2"]=[[2019qxcdg1a]],["role3"]=[[2019qxcdg1b]],["roomBgm"]=[[chalou]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb09_20"]={["dsc"]=[[这里是金陵城的知府衙门。朱红的大门上钉着碗口大的铜钉，闪闪发光，气派非凡。在门口立有两座石狮，张牙舞爪，你不禁感到一阵心悸，还是赶紧离开吧。]],["enterable"]=1,["id"]=[[fb09_20]],["left"]=[[fb09_35]],["name"]=[[衙门]],["permission"]=2,["right"]=[[fb09_21]],["role1"]=[[fb09r20_1]],["role2"]=[[fb09r100_2]],["role3"]=[[fb09r100_3]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb09_21"]={["down"]=[[fb09_17]],["dsc"]=[[这里是金陵镇北边的主要街道，往南通往镇上最热闹的广场，往北则通往长江边，你的左边是衙门，右边是一家钱庄，街道上人来人往，一派繁华的景象。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb09_21]],["left"]=[[fb09_20]],["name"]=[[北街]],["permission"]=1,["right"]=[[fb09_22]],["role1"]=[[fb09r21_1]],["role2"]=[[jqbnpc1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb09_25]],["visible"]=1},["fb09_22"]={["dsc"]=[[这是全国规模最大的一家钱庄，在全国各地都有分店。它发行的银票通行全国钱庄的门口挂着一块很大的金字招牌，上书穆记钱庄。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb09_22]],["left"]=[[fb09_21]],["name"]=[[穆记钱庄]],["permission"]=2,["role1"]=[[fb09r22_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb09_23"]={["down"]=[[fb09_13]],["dsc"]=[[这里是一条幽静狭小的巷子。相传说旧时王谢子弟善著乌衣，因而得名。有道是:“朱雀桥边野草花，乌衣巷口夕阳斜，旧时王谢堂前燕，飞入寻常百姓家。”乌衣巷也因此而名扬四海。]],["enterable"]=1,["id"]=[[fb09_23]],["item1"]=[[yylbsdj1]],["item2"]=[[21xcdfwp]],["item3"]=[[21xiaohanquest4]],["name"]=[[乌衣巷]],["permission"]=2,["righ